   100→/// Compaction result and statistics
   101→#[derive(Debug, Clone)]
   102→pub struct CompactionResult {
   103→    pub bytes_moved: u64,
   104→    pub objects_moved: usize,
   105→    pub time_ms: f64,
   106→    pub fragmentation_before: f64,
   107→    pub fragmentation_after: f64,
   108→}
   109→
   110→/// Heap compaction using LISP2 algorithm
   111→pub struct HeapCompactor {
   112→    address_map: HashMap<usize, usize>,
   113→    compaction_count: usize,
   114→    last_result: Option<CompactionResult>,
   115→}
   116→
   117→impl HeapCompactor {
   118→    pub fn new() -> Self {
   119→        HeapCompactor {
   120→            address_map: HashMap::new(),
   121→            compaction_count: 0,
   122→            last_result: None,
   123→        }
   124→    }
   125→
   126→    /// LISP2 Pass 1: Calculate new addresses
   127→    pub fn calculate_new_addresses(&mut self, heap_objects: &[HeapObject]) -> HashMap<usize, usize> {
   128→        self.address_map.clear();
   129→        let mut new_address = 0x5000usize;
   130→
   131→        for obj in heap_objects {
   132→            if obj.allocated {
   133→                self.address_map.insert(obj.address, new_address);
   134→                new_address += obj.size as usize;
   135→            }
   136→        }
   137→
   138→        self.address_map.clone()
   139→    }
   140→
   141→    /// LISP2 Pass 2: Update references
   142→    pub fn update_stack_references(&self, stack: &mut [u64]) {
   143→        for value in stack {
   144→            let addr = *value as usize;
   145→            if let Some(&new_addr) = self.address_map.get(&addr) {
   146→                *value = new_addr as u64;
   147→            }
   148→        }
   149→    }
   150→
   151→    /// LISP2 Pass 2: Update global references
   152→    pub fn update_global_references(&self, globals: &mut [u64]) {
   153→        for value in globals {
   154→            let addr = *value as usize;
   155→            if let Some(&new_addr) = self.address_map.get(&addr) {
   156→                *value = new_addr as u64;
   157→            }
   158→        }
   159→    }
   160→
   161→    /// Calculate fragmentation ratio
   162→    pub fn calculate_fragmentation(&self, heap_objects: &[HeapObject], heap_size: usize) -> f64 {
   163→        let allocated: u64 = heap_objects
   164→            .iter()
   165→            .filter(|obj| obj.allocated)
   166→            .map(|obj| obj.size)
   167→            .sum();
   168→
   169→        let free: u64 = heap_objects
   170→            .iter()
   171→            .filter(|obj| !obj.allocated)
   172→            .map(|obj| obj.size)
   173→            .sum();
   174→
   175→        if free == 0 {
   176→            0.0
   177→        } else {
   178→            free as f64 / heap_size as f64
   179→        }
   180→    }
   181→
   182→    /// Should trigger compaction?
   183→    pub fn should_compact(&self, heap_objects: &[HeapObject], heap_size: usize) -> bool {
   184→        let fragmentation = self.calculate_fragmentation(heap_objects, heap_size);
   185→        let allocated: u64 = heap_objects
   186→            .iter()
   187→            .filter(|obj| obj.allocated)
   188→            .map(|obj| obj.size)
   189→            .sum();
   190→
   191→        let allocated_ratio = allocated as f64 / heap_size as f64;
   192→
   193→        // Compact if fragmentation > 20% AND allocations > 30% of heap
   194→        fragmentation > 0.20 && allocated_ratio > 0.30
   195→    }
   196→
   197→    /// Get last compaction result
   198→    pub fn last_result(&self) -> Option<&CompactionResult> {
   199→        self.last_result.as_ref()
   200→    }
   201→
   202→    /// Get compaction count
   203→    pub fn compaction_count(&self) -> usize {
   204→        self.compaction_count
   205→    }
   206→}
   207→
   208→impl Default for HeapCompactor {
   209→    fn default() -> Self {
   210→        Self::new()
   211→    }
   212→}
