   214→/// Garbage collector using mark-and-sweep
   215→pub struct GarbageCollector {
   216→    /// Mark set: which objects are reachable
   217→    marked: Vec<bool>,
   218→
   219→    /// Reachable objects during current collection
   220→    reachable: Vec<Reference>,
   221→
   222→    /// Total collections performed
   223→    pub collections: usize,
   224→
   225→    /// Total objects freed
   226→    pub freed_count: usize,
   227→
   228→    /// Track heap objects
   229→    pub heap_objects: Vec<HeapObject>,
   230→
   231→    /// Freed bytes total
   232→    pub freed_bytes: u64,
   233→
   234→    /// Heap compactor for LISP2 algorithm
   235→    pub compactor: HeapCompactor,
   236→
   237→    /// BumpPointer allocator (post-compaction)
   238→    pub bump_allocator: BumpPointerAllocator,
   239→
   240→    /// Compaction statistics
   241→    pub compactions: usize,
   242→}
   243→
   244→impl GarbageCollector {
   245→    /// Create a new garbage collector
   246→    pub fn new() -> Self {
   247→        GarbageCollector {
   248→            marked: vec![false; 16384],
   249→            reachable: Vec::new(),
   250→            collections: 0,
   251→            freed_count: 0,
   252→            heap_objects: Vec::new(),
   253→            freed_bytes: 0,
   254→            compactor: HeapCompactor::new(),
   255→            bump_allocator: BumpPointerAllocator::new(0x5000, 0xFFFE),
   256→            compactions: 0,
   257→        }
   258→    }
   259→
   260→    /// Register a heap allocation
   261→    pub fn register_allocation(&mut self, address: usize, size: u64, obj_type: ObjectType) {
   262→        let obj = HeapObject {
   263→            address,
   264→            size,
   265→            allocated: true,
   266→            marked: false,
   267→            object_type: obj_type,
   268→        };
   269→        self.heap_objects.push(obj);
   270→    }
   271→
   272→    /// Run garbage collection
   273→    ///
   274→    /// # Arguments
   275→    ///
   276→    /// * `stack` - Stack values
   277→    /// * `globals` - Global values
   278→    pub fn collect(&mut self, stack: &[u64], globals: &[u64]) {
   279→        // Mark phase: Find all reachable objects
   280→        self.mark_reachable(stack, globals);
   281→
   282→        // Sweep phase: Free unmarked objects
   283→        self.sweep();
   284→
   285→        // Statistics
   286→        self.collections += 1;
   287→    }
   288→
   289→    /// Mark phase: Find all reachable objects from roots
   290→    pub fn mark_reachable(&mut self, stack: &[u64], globals: &[u64]) {
   291→        // Clear all marks
   292→        for obj in &mut self.heap_objects {
   293→            obj.marked = false;
   294→        }
   295→
   296→        let mut to_visit = Vec::new();
   297→
   298→        // Collect roots
   299→        for &value in stack {
   300→            if self.is_heap_pointer(value) {
   301→                to_visit.push(value as usize);
   302→            }
   303→        }
   304→
   305→        for &value in globals {
   306→            if self.is_heap_pointer(value) {
   307→                to_visit.push(value as usize);
   308→            }
   309→        }
   310→
   311→        // Remove duplicates
   312→        to_visit.sort();
   313→        to_visit.dedup();
   314→
   315→        // DFS traversal
   316→        let mut visited = HashSet::new();
   317→        while let Some(addr) = to_visit.pop() {
   318→            if visited.contains(&addr) {
   319→                continue;
   320→            }
   321→            visited.insert(addr);
   322→
   323→            if let Some(obj) = self.find_object_mut(addr) {
   324→                obj.marked = true;
   325→            }
   326→        }
   327→    }
   328→
   329→    /// Sweep phase: Reclaim unmarked objects
   330→    pub fn sweep(&mut self) {
   331→        for obj in &mut self.heap_objects {
   332→            if !obj.allocated {
   333→                continue;
   334→            }
   335→
   336→            if !obj.marked {
   337→                obj.allocated = false;
   338→                self.freed_count += 1;
   339→                self.freed_bytes += obj.size;
   340→            }
   341→        }
   342→    }
   343→
   344→    /// Compact heap using LISP2 algorithm (Pass 1 & Pass 2)
   345→    pub fn compact(&mut self, stack: &mut [u64], globals: &mut [u64]) {
   346→        let start = Instant::now();
   347→
   348→        // LISP2 Pass 1: Calculate new addresses
   349→        let address_map = self.compactor.calculate_new_addresses(&self.heap_objects);
   350→
   351→        // LISP2 Pass 2: Update references
   352→        self.compactor.update_stack_references(stack);
   353→        self.compactor.update_global_references(globals);
   354→
   355→        // Update object addresses in our tracking
   356→        for obj in &mut self.heap_objects {
   357→            if obj.allocated {
   358→                if let Some(&new_addr) = address_map.get(&obj.address) {
   359→                    obj.address = new_addr;
   360→                }
   361→            }
   362→        }
   363→
   364→        // Update heap pointer to next available space
   365→        let new_heap_ptr = self.heap_objects
   366→            .iter()
   367→            .filter(|obj| obj.allocated)
   368→            .map(|obj| obj.address + obj.size as usize)
   369→            .max()
   370→            .unwrap_or(0x5000);
   371→
   372→        // Reset bump allocator for next allocations
   373→        self.bump_allocator.reset();
   374→        self.bump_allocator.current_ptr = new_heap_ptr;
   375→
   376→        // Statistics
   377→        self.compactions += 1;
   378→    }
   379→
   380→    /// Should compact the heap?
   381→    pub fn should_compact(&self) -> bool {
   382→        self.compactor.should_compact(&self.heap_objects, 0xFFFE - 0x5000)
   383→    }
   384→
   385→    /// Get fragmentation ratio (0.0 to 1.0)
   386→    pub fn fragmentation_ratio(&self) -> f64 {
   387→        self.compactor.calculate_fragmentation(&self.heap_objects, 0xFFFE - 0x5000)
   388→    }
   389→
   390→    /// Get number of compactions performed
   391→    pub fn compaction_count(&self) -> usize {
   392→        self.compactions
   393→    }
   394→
   395→    /// Mark phase: DFS to find reachable objects (legacy interface)
   396→    fn mark(&mut self, addr: usize, _memory: &Memory) -> Result<(), String> {
   397→        if addr >= self.marked.len() {
   398→            return Err(format!("Invalid address: {}", addr));
   399→        }
   400→
   401→        if self.marked[addr] {
   402→            return Ok(()); // Already marked
   403→        }
   404→
   405→        self.marked[addr] = true;
   406→        self.reachable.push(addr);
   407→
   408→        Ok(())
   409→    }
   410→
   411→    /// Sweep phase: Free unmarked objects (legacy interface)
   412→    fn sweep_legacy(&mut self, memory: &mut Memory) -> Result<usize, String> {
   413→        let mut freed = 0;
   414→
   415→        for addr in 0..self.marked.len() {
   416→            if !self.marked[addr] {
   417→                // Free unmarked object
   418→                memory.write(addr, 0)?;
   419→                freed += 1;
   420→            }
   421→        }
   422→
   423→        Ok(freed)
   424→    }
   425→
   426→    /// Check if a value looks like a heap pointer
   427→    fn is_heap_pointer(&self, value: u64) -> bool {
   428→        let addr = value as usize;
   429→        // Heap range: 0x5000 - 0xFFFD
   430→        addr >= 0x5000 && addr <= 0xFFFD
   431→    }
   432→
   433→    /// Find object by address (mutable)
   434→    fn find_object_mut(&mut self, addr: usize) -> Option<&mut HeapObject> {
   435→        self.heap_objects.iter_mut().find(|obj| obj.address == addr)
   436→    }
   437→
   438→    /// Find object by address
   439→    pub fn find_object(&self, addr: usize) -> Option<&HeapObject> {
   440→        self.heap_objects.iter().find(|obj| obj.address == addr)
   441→    }
   442→
   443→    /// Get allocated objects count
   444→    pub fn allocated_objects_count(&self) -> usize {
   445→        self.heap_objects.iter().filter(|obj| obj.allocated).count()
   446→    }
   447→
   448→    /// Get total allocated bytes
   449→    pub fn allocated_bytes(&self) -> u64 {
   450→        self.heap_objects
   451→            .iter()
   452→            .filter(|obj| obj.allocated)
   453→            .map(|obj| obj.size)
   454→            .sum()
   455→    }
   456→
   457→    /// Get garbage collector statistics
   458→    pub fn stats(&self) -> GCStats {
   459→        GCStats {
   460→            collections: self.collections,
   461→            freed_count: self.freed_count,
   462→            marked_count: self.heap_objects.iter().filter(|obj| obj.marked).count(),
   463→            freed_bytes: self.freed_bytes,
   464→        }
   465→    }
   466→}
   467→
   468→impl Default for GarbageCollector {
   469→    fn default() -> Self {
   470→        Self::new()
   471→    }
   472→}
   473→
   474→/// Garbage collector statistics
   475→#[derive(Debug, Clone)]
   476→pub struct GCStats {
   477→    /// Total garbage collections
   478→    pub collections: usize,
   479→
   480→    /// Total objects freed
   481→    pub freed_count: usize,
   482→
   483→    /// Currently marked objects
   484→    pub marked_count: usize,
   485→
   486→    /// Total bytes freed
   487→    pub freed_bytes: u64,
   488→}
