     1→//! Virtual Machine core execution engine
     2→//!
     3→//! This module implements the stack-based VM that executes bytecode instructions.
     4→//!
     5→//! # Architecture
     6→//!
     7→//! - **Memory**: [u64; 16384] = 64KB (8-byte words)
     8→//!   - Stack: 0x0000 - 0x4FFF (20KB, grows upward)
     9→//!   - Heap: 0x5000 - 0xFFFD (44KB)
    10→//!   - Globals: 0xFFFE - 0xFFFF (1KB)
    11→//!
    12→//! - **Registers**:
    13→//!   - PC (Program Counter): Current instruction address
    14→//!   - SP (Stack Pointer): Top of stack
    15→//!   - BP (Base Pointer): Frame base for local variables
    16→//!   - ACC (Accumulator): Temporary value storage
    17→//!
    18→//! - **Call Stack**: Function call frames with return addresses
    19→
    20→use crate::bytecode::BytecodeLoader;
    21→use crate::memory::Memory;
    22→use crate::gc::GarbageCollector;
    23→
    24→/// Call frame for function calls
    25→#[derive(Clone, Debug)]
    26→pub struct CallFrame {
    27→    /// Return PC when function returns
    28→    pub return_pc: usize,
    29→    /// Saved base pointer
    30→    pub saved_bp: usize,
    31→}
    32→
    33→/// Main virtual machine
    34→pub struct VM {
    35→    /// 64KB memory (16384 × 8 bytes)
    36→    pub memory: Memory,
    37→
    38→    /// Program counter (current instruction)
    39→    pub pc: usize,
    40→
    41→    /// Stack pointer (top of stack)
    42→    pub sp: usize,
    43→
    44→    /// Base pointer (frame base)
    45→    pub bp: usize,
    46→
    47→    /// Heap pointer (for array/string allocation)
    48→    pub heap_ptr: usize,
    49→
    50→    /// Bytecode instructions
    51→    pub code: Vec<u8>,
    52→
    53→    /// Function call stack
    54→    pub call_stack: Vec<CallFrame>,
    55→
    56→    /// Garbage collector
    57→    pub gc: GarbageCollector,
    58→}
    59→
    60→impl VM {
    61→    /// Create a new VM instance and load bytecode
    62→    ///
    63→    /// # Arguments
    64→    ///
    65→    /// * `bytecode` - Raw bytecode bytes
    66→    ///
    67→    /// # Returns
    68→    ///
    69→    /// * `Ok(VM)` - Initialized VM
    70→    /// * `Err(String)` - Initialization error
    71→    pub fn new(bytecode: &[u8]) -> Result<Self, String> {
    72→        // Load and validate bytecode
    73→        let loader = BytecodeLoader::new(bytecode)?;
    74→        let code = loader.code();
    75→
    76→        // Initialize VM state
    77→        let mut vm = VM {
    78→            memory: Memory::new(),
    79→            pc: 0,
    80→            sp: 0,
    81→            bp: 0,
    82→            heap_ptr: 0x5000,  // Heap starts at 0x5000 (20KB offset)
    83→            code,
    84→            call_stack: Vec::new(),
    85→            gc: GarbageCollector::new(),
    86→        };
    87→
    88→        // TODO: Load data section and symbol table
    89→
    90→        Ok(vm)
    91→    }
    92→
    93→    /// Run the VM until HALT or end-of-code
    94→    ///
    95→    /// # Returns
    96→    ///
    97→    /// * `Ok(exit_code)` - Program exit code
    98→    /// * `Err(String)` - Runtime error
    99→    pub fn run(&mut self) -> Result<u64, String> {
   100→        loop {
   101→            // Check program end
   102→            if self.pc >= self.code.len() {
   103→                break;
   104→            }
   105→
   106→            // Execute next instruction
   107→            self.step()?;
   108→        }
   109→
   110→        Ok(0) // Default exit code
   111→    }
   112→
   113→    /// Execute one instruction
   114→    ///
   115→    /// # Returns
   116→    ///
   117→    /// * `Ok(())` - Instruction executed successfully
   118→    /// * `Err(String)` - Instruction execution error
   119→    pub fn step(&mut self) -> Result<(), String> {
   120→        // Fetch instruction
   121→        if self.pc >= self.code.len() {
   122→            return Err("Unexpected end of bytecode".to_string());
   123→        }
   124→
   125→        let opcode = self.code[self.pc];
   126→        self.pc += 1;
   127→
   128→        // Decode and execute
   129→        match opcode {
   130→            // Load/Store instructions
   131→            0x01 => self.exec_push()?,
   132→            0x02 => self.exec_pop()?,
   133→            0x03 => self.exec_load()?,
   134→            0x04 => self.exec_store()?,
   135→            0x05 => self.exec_loadg()?,
   136→            0x06 => self.exec_storeg()?,
   137→            0x07 => self.exec_dup()?,
   138→            0x08 => self.exec_swap()?,
   139→
   140→            // Arithmetic instructions
   141→            0x10 => self.exec_add()?,
   142→            0x11 => self.exec_sub()?,
   143→            0x12 => self.exec_mul()?,
   144→            0x13 => self.exec_div()?,
   145→            0x14 => self.exec_mod()?,
   146→            0x15 => self.exec_neg()?,
   147→            0x16 => self.exec_abs()?,
   148→            0x17 => self.exec_incr()?,
   149→
   150→            // Logic instructions
   151→            0x20 => self.exec_and()?,
   152→            0x21 => self.exec_or()?,
   153→            0x22 => self.exec_not()?,
   154→            0x23 => self.exec_xor()?,
   155→            0x24 => self.exec_eq()?,
   156→            0x25 => self.exec_neq()?,
   157→            0x26 => self.exec_lt()?,
   158→            0x27 => self.exec_lte()?,
   159→
   160→            // Control flow instructions
   161→            0x30 => self.exec_jmp()?,
   162→            0x31 => self.exec_jif()?,
   163→            0x32 => self.exec_jit()?,
   164→            0x33 => self.exec_call()?,
   165→            0x34 => self.exec_ret()?,
   166→            0x35 => self.exec_loop()?,
   167→            0x36 => self.exec_cmpjmp()?,
   168→            0x37 => self.exec_nop()?,
   169→
   170→            // Array instructions
   171→            0x40 => self.exec_arralloc()?,
   172→            0x41 => self.exec_arrget()?,
   173→            0x42 => self.exec_arrset()?,
   174→            0x43 => self.exec_arrlen()?,
   175→
   176→            // String instructions
   177→            0x50 => self.exec_stralloc()?,
   178→            0x51 => self.exec_strget()?,
   179→            0x52 => self.exec_strset()?,
   180→            0x53 => self.exec_strlen()?,
   181→
   182→            // Built-in instructions
   183→            0x60 => self.exec_print()?,
   184→            0x61 => self.exec_halt()?,
   185→
   186→            _ => return Err(format!("Unknown opcode: 0x{:02x}", opcode)),
   187→        }
   188→
   189→        Ok(())
   190→    }
   191→
   192→    // ====== Load/Store Instructions ======
   193→
   194→    fn exec_push(&mut self) -> Result<(), String> {
   195→        // Read 8-byte value from bytecode
   196→        let value = self.read_u64()?;
   197→
   198→        // Push value onto stack
   199→        self.push(value)?;
   200→
   201→        Ok(())
   202→    }
   203→
   204→    fn exec_pop(&mut self) -> Result<(), String> {
   205→        // Pop value from stack (discarded)
   206→        let _value = self.pop()?;
   207→
   208→        Ok(())
   209→    }
   210→
   211→    fn exec_load(&mut self) -> Result<(), String> {
   212→        // Read local variable index (1 byte)
   213→        if self.pc >= self.code.len() {
   214→            return Err("Expected operand for LOAD".to_string());
   215→        }
   216→        let index = self.code[self.pc] as usize;
   217→        self.pc += 1;
   218→
   219→        // Calculate address: BP + index
   220→        let addr = self.bp.checked_add(index)
   221→            .ok_or("LOAD address overflow".to_string())?;
   222→
   223→        // Read value from memory
   224→        let value = self.memory.read(addr)?;
   225→
   226→        // Push to stack
   227→        self.push(value)?;
   228→
   229→        Ok(())
   230→    }
   231→
   232→    fn exec_store(&mut self) -> Result<(), String> {
   233→        // Read local variable index (1 byte)
   234→        if self.pc >= self.code.len() {
   235→            return Err("Expected operand for STORE".to_string());
   236→        }
   237→        let index = self.code[self.pc] as usize;
   238→        self.pc += 1;
   239→
   240→        // Pop value from stack
   241→        let value = self.pop()?;
   242→
   243→        // Calculate address: BP + index
   244→        let addr = self.bp.checked_add(index)
   245→            .ok_or("STORE address overflow".to_string())?;
   246→
   247→        // Write to memory
   248→        self.memory.write(addr, value)?;
   249→
   250→        Ok(())
   251→    }
   252→
   253→    fn exec_loadg(&mut self) -> Result<(), String> {
   254→        // Load from global variable
   255→        if self.pc >= self.code.len() {
   256→            return Err("Expected operand for LOADG".to_string());
   257→        }
   258→        let index = self.code[self.pc] as usize;
   259→        self.pc += 1;
   260→
   261→        // Global variables at 0xFFFE + index
   262→        let addr = 0xFFFE + index;
   263→        let value = self.memory.read(addr)?;
   264→        self.push(value)?;
   265→
   266→        Ok(())
   267→    }
   268→
   269→    fn exec_storeg(&mut self) -> Result<(), String> {
   270→        // Store to global variable
   271→        if self.pc >= self.code.len() {
   272→            return Err("Expected operand for STOREG".to_string());
   273→        }
   274→        let index = self.code[self.pc] as usize;
   275→        self.pc += 1;
   276→
   277→        let value = self.pop()?;
   278→        let addr = 0xFFFE + index;
   279→        self.memory.write(addr, value)?;
   280→
   281→        Ok(())
   282→    }
   283→
   284→    fn exec_dup(&mut self) -> Result<(), String> {
   285→        // Duplicate top of stack
   286→        if self.sp == 0 {
   287→            return Err("Stack underflow".to_string());
   288→        }
   289→
   290→        // Read top of stack (without popping)
   291→        let top_value = self.memory.read(self.sp - 1)?;
   292→
   293→        // Push duplicate
   294→        self.push(top_value)?;
   295→
   296→        Ok(())
   297→    }
   298→
   299→    fn exec_swap(&mut self) -> Result<(), String> {
   300→        // Swap top two stack values
   301→        if self.sp < 2 {
   302→            return Err("Stack underflow".to_string());
   303→        }
   304→
   305→        // Read two top values
   306→        let top = self.memory.read(self.sp - 1)?;
   307→        let second = self.memory.read(self.sp - 2)?;
   308→
   309→        // Swap them
   310→        self.memory.write(self.sp - 1, second)?;
   311→        self.memory.write(self.sp - 2, top)?;
   312→
   313→        Ok(())
   314→    }
