   316→    // ====== Built-in Instructions ======
   317→
   318→    fn exec_print(&mut self) -> Result<(), String> {
   319→        // Pop value from stack and print it
   320→        let value = self.pop()?;
   321→
   322→        // Print as signed 64-bit integer
   323→        println!("{}", value as i64);
   324→
   325→        Ok(())
   326→    }
