   328→    fn exec_halt(&mut self) -> Result<(), String> {
   329→        // Pop exit code and halt
   330→        let exit_code = self.pop()?;
   331→
   332→        // Exit the program
   333→        std::process::exit(exit_code as i32);
   334→    }
