   336→    // ====== Arithmetic Instructions ======
   337→
   338→    fn exec_add(&mut self) -> Result<(), String> {
   339→        // Pop two values (order matters!)
   340→        let b = self.pop()?;  // Second operand (top)
   341→        let a = self.pop()?;  // First operand
   342→
   343→        // Add them
   344→        let result = a.wrapping_add(b);
   345→
   346→        // Push result
   347→        self.push(result)?;
   348→
   349→        Ok(())
   350→    }
   351→
   352→    fn exec_sub(&mut self) -> Result<(), String> {
   353→        // Pop two values
   354→        let b = self.pop()?;  // Subtrahend (top)
   355→        let a = self.pop()?;  // Minuend
   356→
   357→        // Subtract them
   358→        let result = a.wrapping_sub(b);
   359→
   360→        // Push result
   361→        self.push(result)?;
   362→
   363→        Ok(())
   364→    }
   365→
   366→    fn exec_mul(&mut self) -> Result<(), String> {
   367→        // Pop two values
   368→        let b = self.pop()?;
   369→        let a = self.pop()?;
   370→
   371→        // Multiply them
   372→        let result = a.wrapping_mul(b);
   373→
   374→        // Push result
   375→        self.push(result)?;
   376→
   377→        Ok(())
   378→    }
   379→
   380→    fn exec_div(&mut self) -> Result<(), String> {
   381→        // Pop two values
   382→        let b = self.pop()?;  // Divisor
   383→        let a = self.pop()?;  // Dividend
   384→
   385→        // Check for division by zero
   386→        if b == 0 {
   387→            return Err("Division by zero".to_string());
   388→        }
   389→
   390→        // Perform signed division
   391→        let a_i64 = a as i64;
   392→        let b_i64 = b as i64;
   393→        let result = a_i64.wrapping_div(b_i64);
   394→
   395→        // Push result
   396→        self.push(result as u64);
   397→
   398→        Ok(())
   399→    }
   400→
   401→    fn exec_mod(&mut self) -> Result<(), String> {
   402→        // Pop two values
   403→        let b = self.pop()?;  // Divisor
   404→        let a = self.pop()?;  // Dividend
   405→
   406→        // Check for modulo by zero
   407→        if b == 0 {
   408→            return Err("Modulo by zero".to_string());
   409→        }
   410→
   411→        // Perform signed modulo
   412→        let a_i64 = a as i64;
   413→        let b_i64 = b as i64;
   414→        let result = a_i64.wrapping_rem(b_i64);
   415→
   416→        // Push result
   417→        self.push(result as u64);
   418→
   419→        Ok(())
   420→    }
   421→
   422→    fn exec_neg(&mut self) -> Result<(), String> {
   423→        // Pop value
   424→        let a = self.pop()?;
   425→
   426→        // Perform negation (two's complement)
   427→        let a_i64 = a as i64;
   428→        let result = a_i64.wrapping_neg();
   429→
   430→        // Push result
   431→        self.push(result as u64);
   432→
   433→        Ok(())
   434→    }
   435→
   436→    fn exec_abs(&mut self) -> Result<(), String> {
   437→        // Pop value
   438→        let a = self.pop()?;
   439→
   440→        // Perform absolute value
   441→        let a_i64 = a as i64;
   442→        let result = a_i64.abs();
   443→
   444→        // Push result
   445→        self.push(result as u64);
   446→
   447→        Ok(())
   448→    }
   449→
   450→    fn exec_incr(&mut self) -> Result<(), String> {
   451→        // Pop value
   452→        let a = self.pop()?;
   453→
   454→        // Increment by 1
   455→        let result = a.wrapping_add(1);
   456→
   457→        // Push result
   458→        self.push(result)?;
   459→
   460→        Ok(())
   461→    }
