   518→    }
   519→
   520→    fn exec_eq(&mut self) -> Result<(), String> {
   521→        // Pop two values
   522→        let b = self.pop()?;
   523→        let a = self.pop()?;
   524→
   525→        // Compare equality: 1 if equal, 0 if not
   526→        let result = if a == b { 1 } else { 0 };
   527→
   528→        // Push result
   529→        self.push(result)?;
   530→
   531→        Ok(())
   532→    }
   533→
   534→    fn exec_neq(&mut self) -> Result<(), String> {
   535→        // Pop two values
   536→        let b = self.pop()?;
   537→        let a = self.pop()?;
   538→
   539→        // Compare inequality: 1 if not equal, 0 if equal
   540→        let result = if a != b { 1 } else { 0 };
   541→
   542→        // Push result
   543→        self.push(result)?;
   544→
   545→        Ok(())
   546→    }
   547→
   548→    fn exec_lt(&mut self) -> Result<(), String> {
