   580→    // ====== Control Flow Instructions ======
   581→
   582→    fn exec_jmp(&mut self) -> Result<(), String> {
   583→        // Read 4-byte address from bytecode
   584→        if self.pc + 4 > self.code.len() {
   585→            return Err("JMP: Expected 4-byte address".to_string());
   586→        }
   587→
   588→        let addr_bytes = &self.code[self.pc..self.pc + 4];
   589→        let addr = u32::from_be_bytes([
   590→            addr_bytes[0], addr_bytes[1], addr_bytes[2], addr_bytes[3],
   591→        ]) as usize;
   592→
   593→        self.pc += 4;
   594→
   595→        // Validate and jump
   596→        if addr >= self.code.len() {
   597→            return Err("JMP: Target address out of bounds".to_string());
   598→        }
   599→
   600→        self.pc = addr;
   601→        Ok(())
   602→    }
   603→
   604→    fn exec_jif(&mut self) -> Result<(), String> {
   605→        // Read 4-byte address
   606→        if self.pc + 4 > self.code.len() {
   607→            return Err("JIF: Expected 4-byte address".to_string());
   608→        }
   609→
   610→        let addr_bytes = &self.code[self.pc..self.pc + 4];
   611→        let addr = u32::from_be_bytes([
   612→            addr_bytes[0], addr_bytes[1], addr_bytes[2], addr_bytes[3],
   613→        ]) as usize;
   614→
   615→        self.pc += 4;
   616→
   617→        // Pop condition
   618→        let cond = self.pop()?;
   619→
   620→        // Jump if false (cond == 0)
   621→        if cond == 0 {
   622→            if addr >= self.code.len() {
   623→                return Err("JIF: Target address out of bounds".to_string());
   624→            }
   625→            self.pc = addr;
   626→        }
   627→
   628→        Ok(())
   629→    }
   630→
   631→    fn exec_jit(&mut self) -> Result<(), String> {
   632→        // Read 4-byte address
   633→        if self.pc + 4 > self.code.len() {
   634→            return Err("JIT: Expected 4-byte address".to_string());
   635→        }
   636→
   637→        let addr_bytes = &self.code[self.pc..self.pc + 4];
   638→        let addr = u32::from_be_bytes([
   639→            addr_bytes[0], addr_bytes[1], addr_bytes[2], addr_bytes[3],
   640→        ]) as usize;
   641→
   642→        self.pc += 4;
   643→
   644→        // Pop condition
   645→        let cond = self.pop()?;
   646→
   647→        // Jump if true (cond != 0)
   648→        if cond != 0 {
   649→            if addr >= self.code.len() {
   650→                return Err("JIT: Target address out of bounds".to_string());
   651→            }
   652→            self.pc = addr;
   653→        }
   654→
   655→        Ok(())
   656→    }
   657→
   658→    fn exec_call(&mut self) -> Result<(), String> {
   659→        // Read 4-byte target address
   660→        if self.pc + 4 > self.code.len() {
   661→            return Err("CALL: Expected 4-byte address".to_string());
   662→        }
   663→
   664→        let addr_bytes = &self.code[self.pc..self.pc + 4];
   665→        let target_addr = u32::from_be_bytes([
   666→            addr_bytes[0], addr_bytes[1], addr_bytes[2], addr_bytes[3],
   667→        ]) as usize;
   668→
   669→        // Save return address (after reading the address)
   670→        let return_addr = self.pc + 4;
   671→
   672→        // Validate target
   673→        if target_addr >= self.code.len() {
   674→            return Err("CALL: Target address out of bounds".to_string());
   675→        }
   676→
   677→        // Push call frame
   678→        self.call_stack.push(CallFrame {
   679→            return_pc: return_addr,
   680→            saved_bp: self.bp,
   681→        });
   682→
   683→        // Set BP to current SP for local variables
   684→        self.bp = self.sp;
   685→
   686→        // Jump to function
   687→        self.pc = target_addr;
   688→
   689→        Ok(())
   690→    }
   691→
   692→    fn exec_ret(&mut self) -> Result<(), String> {
   693→        // Pop call frame
   694→        let frame = self.call_stack.pop()
   695→            .ok_or("RET: Call stack underflow".to_string())?;
   696→
   697→        // Restore base pointer
   698→        self.bp = frame.saved_bp;
   699→
   700→        // Jump to return address
   701→        self.pc = frame.return_pc;
   702→
   703→        Ok(())
   704→    }
   705→
   706→    fn exec_loop(&mut self) -> Result<(), String> {
   707→        // Read 4-byte loop address
   708→        if self.pc + 4 > self.code.len() {
   709→            return Err("LOOP: Expected 4-byte address".to_string());
   710→        }
   711→
   712→        let addr_bytes = &self.code[self.pc..self.pc + 4];
   713→        let loop_addr = u32::from_be_bytes([
   714→            addr_bytes[0], addr_bytes[1], addr_bytes[2], addr_bytes[3],
   715→        ]) as usize;
   716→
   717→        self.pc += 4;
   718→
   719→        // Pop loop counter
   720→        let counter = self.pop()?;
   721→
   722→        if counter > 0 {
   723→            // Decrement and push back
   724→            let new_counter = counter - 1;
   725→            self.push(new_counter)?;
   726→
   727→            // Jump back to loop
   728→            if loop_addr >= self.code.len() {
   729→                return Err("LOOP: Target address out of bounds".to_string());
   730→            }
   731→            self.pc = loop_addr;
   732→        }
   733→
   734→        Ok(())
   735→    }
   736→
   737→    fn exec_cmpjmp(&mut self) -> Result<(), String> {
   738→        // Read 4-byte address
   739→        if self.pc + 4 > self.code.len() {
   740→            return Err("CMPJMP: Expected 4-byte address".to_string());
   741→        }
   742→
   743→        let addr_bytes = &self.code[self.pc..self.pc + 4];
   744→        let addr = u32::from_be_bytes([
   745→            addr_bytes[0], addr_bytes[1], addr_bytes[2], addr_bytes[3],
   746→        ]) as usize;
   747→
   748→        self.pc += 4;
   749→
   750→        // Pop two values
   751→        let b = self.pop()?;
   752→        let a = self.pop()?;
   753→
   754→        // Jump if equal
   755→        if a == b {
   756→            if addr >= self.code.len() {
   757→                return Err("CMPJMP: Target address out of bounds".to_string());
   758→            }
   759→            self.pc = addr;
   760→        }
   761→
   762→        Ok(())
   763→    }
   764→
   765→    fn exec_nop(&mut self) -> Result<(), String> {
   766→        // No operation - just continue
   767→        Ok(())
   768→    }
   769→
   770→    // ====== Array Instructions ======
   771→
   772→    fn exec_arralloc(&mut self) -> Result<(), String> {
   773→        // Pop array size
   774→        let size = self.pop()?;
   775→
   776→        // Get current heap pointer
   777→        let array_addr = self.heap_ptr;
   778→
   779→        // Check heap bounds (heap: 0x5000 - 0xFFFD, ~28K words)
   780→        if array_addr + size as usize + 1 >= 0xFFFE {
   781→            return Err("ARRALLOC: Heap overflow".to_string());
   782→        }
   783→
   784→        // Write metadata (length)
   785→        self.memory.write(array_addr, size)?;
   786→
   787→        // Initialize array elements to 0
   788→        for i in 0..size as usize {
   789→            self.memory.write(array_addr + 1 + i, 0)?;
   790→        }
   791→
   792→        // Update heap pointer
   793→        self.heap_ptr += (size as usize) + 1;
   794→
   795→        // Push array address
   796→        self.push(array_addr as u64)?;
   797→
   798→        Ok(())
   799→    }
   800→
   801→    fn exec_arrget(&mut self) -> Result<(), String> {
   802→        // Pop index
   803→        let index = self.pop()?;
   804→
   805→        // Pop array address
   806→        let array_addr = self.pop()? as usize;
   807→
   808→        // Read array length
   809→        let length = self.memory.read(array_addr)?;
   810→
   811→        // Check bounds
   812→        if index >= length {
   813→            return Err(format!("ARRGET: Index out of bounds: {} >= {}", index, length));
   814→        }
   815→
   816→        // Read element
   817→        let element = self.memory.read(array_addr + 1 + index as usize)?;
   818→
   819→        // Push element
   820→        self.push(element)?;
   821→
   822→        Ok(())
   823→    }
   824→
   825→    fn exec_arrset(&mut self) -> Result<(), String> {
   826→        // Pop value
   827→        let value = self.pop()?;
   828→
   829→        // Pop index
   830→        let index = self.pop()?;
   831→
   832→        // Pop array address
   833→        let array_addr = self.pop()? as usize;
   834→
   835→        // Read array length
   836→        let length = self.memory.read(array_addr)?;
   837→
   838→        // Check bounds
   839→        if index >= length {
   840→            return Err(format!("ARRSET: Index out of bounds: {} >= {}", index, length));
   841→        }
   842→
   843→        // Write element
   844→        self.memory.write(array_addr + 1 + index as usize, value)?;
   845→
   846→        Ok(())
   847→    }
   848→
   849→    fn exec_arrlen(&mut self) -> Result<(), String> {
   850→        // Pop array address
   851→        let array_addr = self.pop()? as usize;
   852→
   853→        // Check if address is in valid heap range
   854→        if array_addr < 0x5000 || array_addr >= 0xFFFE {
   855→            return Err("ARRLEN: Invalid array address".to_string());
   856→        }
   857→
   858→        // Read array length
   859→        let length = self.memory.read(array_addr)?;
   860→
   861→        // Push length
   862→        self.push(length)?;
   863→
   864→        Ok(())
   865→    }
   866→
   867→    // ====== String Instructions ======
   868→
   869→    fn exec_stralloc(&mut self) -> Result<(), String> {
   870→        // Pop string length
   871→        let length = self.pop()?;
   872→
   873→        // Get current heap pointer
   874→        let string_addr = self.heap_ptr;
   875→
   876→        // Check heap bounds
   877→        if string_addr + length as usize + 1 >= 0xFFFE {
   878→            return Err("STRALLOC: Heap overflow".to_string());
   879→        }
   880→
   881→        // Write metadata (length)
   882→        self.memory.write(string_addr, length)?;
   883→
   884→        // Initialize string to 0 (null bytes)
   885→        for i in 0..length as usize {
   886→            self.memory.write(string_addr + 1 + i, 0)?;
   887→        }
   888→
   889→        // Update heap pointer
   890→        self.heap_ptr += (length as usize) + 1;
   891→
   892→        // Push string address
   893→        self.push(string_addr as u64)?;
   894→
   895→        Ok(())
   896→    }
   897→
   898→    fn exec_strget(&mut self) -> Result<(), String> {
   899→        // Pop index
   900→        let index = self.pop()?;
   901→
   902→        // Pop string address
   903→        let string_addr = self.pop()? as usize;
   904→
   905→        // Read string length
   906→        let length = self.memory.read(string_addr)?;
   907→
   908→        // Check bounds
   909→        if index >= length {
   910→            return Err(format!("STRGET: Index out of bounds: {} >= {}", index, length));
   911→        }
   912→
   913→        // Read character
   914→        let char_val = self.memory.read(string_addr + 1 + index as usize)?;
   915→
   916→        // Push character
   917→        self.push(char_val)?;
   918→
   919→        Ok(())
   920→    }
   921→
   922→    fn exec_strset(&mut self) -> Result<(), String> {
   923→        // Pop character value
   924→        let char_val = self.pop()?;
   925→
   926→        // Pop index
   927→        let index = self.pop()?;
   928→
   929→        // Pop string address
   930→        let string_addr = self.pop()? as usize;
   931→
   932→        // Read string length
   933→        let length = self.memory.read(string_addr)?;
   934→
   935→        // Check bounds
   936→        if index >= length {
   937→            return Err(format!("STRSET: Index out of bounds: {} >= {}", index, length));
   938→        }
   939→
   940→        // Write character (store in lower 8 bits)
   941→        let masked_char = char_val & 0xFF;
   942→        self.memory.write(string_addr + 1 + index as usize, masked_char)?;
   943→
   944→        Ok(())
   945→    }
   946→
   947→    fn exec_strlen(&mut self) -> Result<(), String> {
   948→        // Pop string address
   949→        let string_addr = self.pop()? as usize;
   950→
   951→        // Check if address is in valid heap range
   952→        if string_addr < 0x5000 || string_addr >= 0xFFFE {
   953→            return Err("STRLEN: Invalid string address".to_string());
   954→        }
   955→
   956→        // Read string length
   957→        let length = self.memory.read(string_addr)?;
   958→
   959→        // Push length
   960→        self.push(length)?;
   961→
   962→        Ok(())
   963→    }
   964→
   965→    // ====== Helper Methods ======
   966→
   967→    /// Push a value onto the stack
   968→    pub fn push(&mut self, value: u64) -> Result<(), String> {
   969→        if self.sp >= 0x5000 {
   970→            return Err("Stack overflow".to_string());
   971→        }
   972→        self.memory.write(self.sp, value)?;
   973→        self.sp += 1;
   974→        Ok(())
   975→    }
   976→
   977→    /// Pop a value from the stack
   978→    pub fn pop(&mut self) -> Result<u64, String> {
   979→        if self.sp == 0 {
   980→            return Err("Stack underflow".to_string());
   981→        }
   982→        self.sp -= 1;
   983→        self.memory.read(self.sp)
   984→    }
   985→
   986→    /// Read 8-byte value from code at current PC
   987→    pub fn read_u64(&mut self) -> Result<u64, String> {
   988→        if self.pc + 8 > self.code.len() {
   989→            return Err("Unexpected end of bytecode".to_string());
   990→        }
   991→
   992→        let bytes = &self.code[self.pc..self.pc + 8];
   993→        self.pc += 8;
   994→
   995→        Ok(u64::from_be_bytes([
   996→            bytes[0], bytes[1], bytes[2], bytes[3],
   997→            bytes[4], bytes[5], bytes[6], bytes[7],
   998→        ]))
   999→    }
  1000→}
  1001→
