    51→/// Array operations
    52→
    53→/// Get array length
    54→///
    55→/// Arrays are stored with length prefix in first 64-bit word
    56→pub fn array_length(array_addr: usize, memory: &Memory) -> Result<usize, String> {
    57→    let len_value = memory.read(array_addr)?;
    58→    Ok(len_value as usize)
    59→}
    60→
    61→/// Read array element
    62→///
    63→/// # Arguments
    64→///
    65→/// * `array_addr` - Base address of array
    66→/// * `index` - Element index
    67→/// * `memory` - Memory instance
    68→pub fn array_get(
    69→    array_addr: usize,
    70→    index: usize,
    71→    memory: &Memory,
    72→) -> Result<u64, String> {
    73→    let len = array_length(array_addr, memory)?;
    74→    if index >= len {
    75→        return Err(format!("Array index out of bounds: {} >= {}", index, len));
    76→    }
    77→    // Array elements start at array_addr + 1 (after length)
    78→    memory.read(array_addr + 1 + index)
    79→}
    80→
    81→/// Write array element
    82→///
    83→/// # Arguments
    84→///
    85→/// * `array_addr` - Base address of array
    86→/// * `index` - Element index
    87→/// * `value` - Value to write
    88→/// * `memory` - Memory instance
    89→pub fn array_set(
    90→    array_addr: usize,
    91→    index: usize,
    92→    value: u64,
    93→    memory: &mut Memory,
    94→) -> Result<(), String> {
    95→    let len = array_length(array_addr, memory)?;
    96→    if index >= len {
    97→        return Err(format!("Array index out of bounds: {} >= {}", index, len));
    98→    }
    99→    // Array elements start at array_addr + 1 (after length)
   100→    memory.write(array_addr + 1 + index, value)
   101→}
