   103→/// String operations
   104→
   105→/// Get string length
   106→///
   107→/// Strings are stored with length prefix in first 64-bit word (as UTF-8 byte count)
   108→pub fn string_length(string_addr: usize, memory: &Memory) -> Result<usize, String> {
   109→    let len_value = memory.read(string_addr)?;
   110→    Ok(len_value as usize)
   111→}
   112→
   113→/// Read string character
   114→///
   115→/// # Arguments
   116→///
   117→/// * `string_addr` - Base address of string
   118→/// * `index` - Character index (in bytes)
   119→/// * `memory` - Memory instance
   120→pub fn string_get(
   121→    string_addr: usize,
   122→    index: usize,
   123→    memory: &Memory,
   124→) -> Result<u8, String> {
   125→    let len = string_length(string_addr, memory)?;
   126→    if index >= len {
   127→        return Err(format!("String index out of bounds: {} >= {}", index, len));
   128→    }
   129→    // String data starts at string_addr + 1
   130→    // Each u64 contains 8 bytes, need to extract the right byte
   131→    let word_addr = string_addr + 1 + (index / 8);
   132→    let word = memory.read(word_addr)?;
   133→    let byte_offset = index % 8;
   134→    let byte_value = ((word >> (byte_offset * 8)) & 0xFF) as u8;
   135→    Ok(byte_value)
   136→}
