     1→//! Memory management
     2→//!
     3→//! Manages the 64KB memory space with stack, heap, and global regions.
     4→//!
     5→//! # Memory Layout
     6→//!
     7→//! ```text
     8→//! 0x0000 ┌──────────────────────┐
     9→//!        │ Stack (20KB)         │  0x0000 - 0x4FFF
    10→//!        │ (grows upward)       │
    11→//! 0x5000 ├──────────────────────┤
    12→//!        │ Heap (44KB)          │  0x5000 - 0xFFFD
    13→//!        │ (dynamic objects)    │
    14→//! 0xFFFE ├──────────────────────┤
    15→//!        │ Globals (1KB)        │  0xFFFE - 0xFFFF
    16→//! 0xFFFF └──────────────────────┘
    17→//! ```
    18→
    19→/// Stack region start (0x0000)
    20→pub const STACK_START: usize = 0x0000;
    21→
    22→/// Stack region end (0x4FFF, 20KB)
    23→pub const STACK_END: usize = 0x5000;
    24→
    25→/// Heap region start (0x5000)
    26→pub const HEAP_START: usize = 0x5000;
    27→
    28→/// Heap region end (0xFFFD, 44KB)
    29→pub const HEAP_END: usize = 0xFFFE;
    30→
    31→/// Global region start (0xFFFE)
    32→pub const GLOBALS_START: usize = 0xFFFE;
    33→
    34→/// Global region end (0xFFFF, 1KB)
    35→pub const GLOBALS_END: usize = 0x10000;
    36→
    37→/// Total memory size: 64KB = 16384 × 8 bytes
    38→pub const MEMORY_SIZE: usize = 16384;
    39→
    40→/// Memory manager
    41→pub struct Memory {
    42→    /// Raw memory: 16384 × u64 = 64KB
    43→    data: [u64; MEMORY_SIZE],
    44→}
    45→
    46→impl Memory {
    47→    /// Create a new memory instance
    48→    pub fn new() -> Self {
    49→        Memory {
    50→            data: [0u64; MEMORY_SIZE],
    51→        }
    52→    }
    53→
    54→    /// Read a 64-bit value from memory
    55→    ///
    56→    /// # Arguments
    57→    ///
    58→    /// * `addr` - Memory address (in 64-bit words, 0-16383)
    59→    ///
    60→    /// # Returns
    61→    ///
    62→    /// * `Ok(value)` - Value at address
    63→    /// * `Err(String)` - Address out of bounds
    64→    pub fn read(&self, addr: usize) -> Result<u64, String> {
    65→        if addr >= MEMORY_SIZE {
    66→            return Err(format!("Memory access out of bounds: {}", addr));
    67→        }
    68→        Ok(self.data[addr])
    69→    }
    70→
    71→    /// Write a 64-bit value to memory
    72→    ///
    73→    /// # Arguments
    74→    ///
    75→    /// * `addr` - Memory address (in 64-bit words, 0-16383)
    76→    /// * `value` - Value to write
    77→    ///
    78→    /// # Returns
    79→    ///
    80→    /// * `Ok(())` - Write successful
    81→    /// * `Err(String)` - Address out of bounds
    82→    pub fn write(&mut self, addr: usize, value: u64) -> Result<(), String> {
    83→        if addr >= MEMORY_SIZE {
    84→            return Err(format!("Memory access out of bounds: {}", addr));
    85→        }
    86→        self.data[addr] = value;
    87→        Ok(())
    88→    }
    89→
    90→    /// Stack push
    91→    pub fn stack_push(&mut self, sp: &mut usize, value: u64) -> Result<(), String> {
    92→        if *sp >= STACK_END {
    93→            return Err("Stack overflow".to_string());
    94→        }
    95→        self.write(*sp, value)?;
    96→        *sp += 1;
    97→        Ok(())
    98→    }
    99→
   100→    /// Stack pop
   101→    pub fn stack_pop(&mut self, sp: &mut usize) -> Result<u64, String> {
   102→        if *sp == 0 {
   103→            return Err("Stack underflow".to_string());
   104→        }
   105→        *sp -= 1;
   106→        self.read(*sp)
   107→    }
   108→
   109→    /// Allocate memory on heap
   110→    ///
   111→    /// TODO: Implement proper heap allocation with alignment
   112→    pub fn heap_allocate(&mut self, size: usize) -> Result<usize, String> {
   113→        // TODO: Implement first-fit allocation
   114→        // For now, return fixed address
   115→        if size > (HEAP_END - HEAP_START) {
   116→            return Err("Heap allocation too large".to_string());
   117→        }
   118→        Ok(HEAP_START)
   119→    }
   120→
   121→    /// Get total memory usage (for statistics)
   122→    pub fn total_usage(&self) -> usize {
   123→        MEMORY_SIZE
   124→    }
   125→
   126→    /// Clear memory (for testing)
   127→    pub fn clear(&mut self) {
   128→        self.data = [0u64; MEMORY_SIZE];
   129→    }
   130→}
   131→
   132→impl Default for Memory {
   133→    fn default() -> Self {
   134→        Self::new()
   135→    }
   136→}
