     1→/**
     2→ * FreeLang Evaluator (JavaScript)
     3→ * Abstract Syntax Tree (AST) 실행
     4→ */
     5→
     6→const runtime = require('./runtime');
     7→const moduleLoader = require('./module-loader');
     8→const {
     9→  Program, VariableDeclaration, FunctionDeclaration, BlockStatement, ExpressionStatement,
    10→  IfStatement, WhileStatement, ForStatement, ForInStatement, ReturnStatement,
    11→  BreakStatement, ContinueStatement, BinaryExpression, UnaryExpression, LogicalExpression,
    12→  CallExpression, MemberExpression, AssignmentExpression, ConditionalExpression,
    13→  ArrayExpression, ObjectExpression, Property, FunctionExpression, Identifier, Literal,
    14→  TryCatchStatement, CatchClause, ThrowStatement, FStringLiteral
    15→} = require('./parser');
    16→
    17→// Control flow signals
    18→const ControlSignal = {
    19→  RETURN: 'return',
    20→  BREAK: 'break',
    21→  CONTINUE: 'continue'
    22→};
    23→
    24→class Environment {
    25→  constructor(parent = null) {
    26→    this.parent = parent;
    27→    this.vars = new Map();
    28→  }
    29→
    30→  define(name, value) {
    31→    this.vars.set(name, value);
    32→  }
    33→
    34→  get(name) {
    35→    if (this.vars.has(name)) {
    36→      return this.vars.get(name);
    37→    }
    38→    if (this.parent) {
    39→      return this.parent.get(name);
    40→    }
    41→    throw new Error(`Undefined variable: ${name}`);
    42→  }
    43→
    44→  set(name, value) {
    45→    if (this.vars.has(name)) {
    46→      this.vars.set(name, value);
    47→      return;
    48→    }
    49→    if (this.parent) {
    50→      this.parent.set(name, value);
    51→      return;
    52→    }
    53→    throw new Error(`Undefined variable: ${name}`);
    54→  }
    55→
    56→  has(name) {
    57→    if (this.vars.has(name)) return true;
    58→    if (this.parent) return this.parent.has(name);
    59→    return false;
    60→  }
    61→}
    62→
    63→class ReturnValue extends Error {
    64→  constructor(value) {
    65→    super();
    66→    this.value = value;
    67→    this.isReturn = true;
    68→  }
    69→}
    70→
    71→class BreakException extends Error {
    72→  constructor() {
    73→    super();
    74→    this.isBreak = true;
    75→  }
    76→}
    77→
    78→class ContinueException extends Error {
    79→  constructor() {
    80→    super();
    81→    this.isContinue = true;
    82→  }
    83→}
    84→
    85→class FreeLangFunction {
    86→  constructor(params, body, closure, name) {
    87→    this.params = params;
    88→    this.body = body;
    89→    this.closure = closure;
    90→    this.name = name || '<anonymous>';
    91→  }
    92→
    93→  call(evaluator, args) {
    94→    const localEnv = new Environment(this.closure);
    95→    for (let i = 0; i < this.params.length; i++) {
    96→      localEnv.define(this.params[i], args[i] || null);
    97→    }
    98→
    99→    try {
   100→      evaluator.executeBlock(this.body.statements || [this.body], localEnv);
   101→      return null;
   102→    } catch (e) {
   103→      if (e.isReturn) {
   104→        return e.value;
   105→      }
   106→      throw e;
   107→    }
   108→  }
   109→
   110→  toString() {
   111→    return `[Function: ${this.name}]`;
   112→  }
   113→}
   114→
   115→class Evaluator {
   116→  constructor() {
   117→    this.globalEnv = new Environment();
   118→    this.currentEnv = this.globalEnv;
   119→
   120→    // Inject built-in functions from runtime
   121→    for (const [name, fn] of Object.entries(runtime)) {
   122→      if (typeof fn === 'function') {
   123→        this.globalEnv.define(name, fn);
   124→      }
   125→    }
   126→
   127→    // Inject require() function for module loading
   128→    this.globalEnv.define('require', (moduleName) => {
   129→      return moduleLoader.require(moduleName);
   130→    });
   131→  }
   132→
   133→  evaluate(ast) {
   134→    return this.eval(ast, this.globalEnv);
   135→  }
   136→
   137→  eval(node, env) {
   138→    const prevEnv = this.currentEnv;
   139→    this.currentEnv = env;
   140→
   141→    try {
   142→      if (node instanceof Program) {
   143→        let result = null;
   144→        for (const stmt of node.statements) {
   145→          result = this.eval(stmt, env);
   146→        }
   147→        return result;
   148→      }
   149→
   150→      if (node instanceof VariableDeclaration) {
   151→        let value = null;
   152→        if (node.init) {
   153→          value = this.eval(node.init, env);
   154→        }
   155→        env.define(node.name, value);
   156→        return value;
   157→      }
   158→
   159→      if (node instanceof FunctionDeclaration) {
   160→        const fn = new FreeLangFunction(node.params, node.body, env, node.name);
   161→        env.define(node.name, fn);
   162→        return fn;
   163→      }
   164→
   165→      if (node instanceof BlockStatement) {
   166→        this.executeBlock(node.statements, env);
   167→        return null;
   168→      }
   169→
   170→      if (node instanceof ExpressionStatement) {
   171→        return this.eval(node.expression, env);
   172→      }
   173→
   174→      if (node instanceof IfStatement) {
   175→        const test = this.isTruthy(this.eval(node.test, env));
   176→        if (test) {
   177→          return this.eval(node.consequent, env);
   178→        } else if (node.alternate) {
   179→          return this.eval(node.alternate, env);
   180→        }
   181→        return null;
   182→      }
   183→
   184→      if (node instanceof WhileStatement) {
   185→        let result = null;
   186→        while (this.isTruthy(this.eval(node.test, env))) {
   187→          try {
   188→            result = this.eval(node.body, env);
   189→          } catch (e) {
   190→            if (e.isBreak) break;
   191→            if (e.isContinue) continue;
   192→            throw e;
   193→          }
   194→        }
   195→        return result;
   196→      }
   197→
   198→      if (node instanceof ForStatement) {
   199→        const loopEnv = new Environment(env);
   200→        if (node.init) {
   201→          this.eval(node.init, loopEnv);
   202→        }
   203→
   204→        let result = null;
   205→        while (!node.test || this.isTruthy(this.eval(node.test, loopEnv))) {
   206→          try {
   207→            result = this.eval(node.body, loopEnv);
   208→          } catch (e) {
   209→            if (e.isBreak) break;
   210→            if (e.isContinue) {
   211→              if (node.update) {
   212→                this.eval(node.update, loopEnv);
   213→              }
   214→              continue;
   215→            }
   216→            throw e;
   217→          }
   218→
   219→          if (node.update) {
   220→            this.eval(node.update, loopEnv);
   221→          }
   222→        }
   223→        return result;
   224→      }
   225→
   226→      if (node instanceof ForInStatement) {
   227→        const iterable = this.eval(node.right, env);
   228→        let result = null;
   229→        const loopEnv = new Environment(env);
   230→
   231→        if (Array.isArray(iterable)) {
   232→          for (const item of iterable) {
   233→            loopEnv.define(node.left, item);
   234→            try {
   235→              result = this.eval(node.body, loopEnv);
   236→            } catch (e) {
   237→              if (e.isBreak) break;
   238→              if (e.isContinue) continue;
   239→              throw e;
   240→            }
   241→          }
   242→        } else if (typeof iterable === 'object' && iterable !== null) {
   243→          for (const key of Object.keys(iterable)) {
   244→            loopEnv.define(node.left, key);
   245→            try {
   246→              result = this.eval(node.body, loopEnv);
   247→            } catch (e) {
   248→              if (e.isBreak) break;
   249→              if (e.isContinue) continue;
   250→              throw e;
   251→            }
   252→          }
   253→        }
   254→        return result;
   255→      }
   256→
   257→      if (node instanceof ReturnStatement) {
   258→        let value = null;
   259→        if (node.argument) {
   260→          value = this.eval(node.argument, env);
   261→        }
   262→        throw new ReturnValue(value);
   263→      }
   264→
   265→      if (node instanceof BreakStatement) {
   266→        throw new BreakException();
   267→      }
   268→
   269→      if (node instanceof ContinueStatement) {
   270→        throw new ContinueException();
   271→      }
   272→
   273→      if (node instanceof TryCatchStatement) {
   274→        let result = null;
   275→        let caught = false;
   276→
   277→        try {
   278→          result = this.eval(node.tryBlock, env);
   279→        } catch (e) {
   280→          if (node.catchClause) {
   281→            // Create a new environment for the catch block
   282→            const catchEnv = new Environment(env);
   283→            catchEnv.define(node.catchClause.param, e.message || e);
   284→            try {
   285→              result = this.eval(node.catchClause.body, catchEnv);
   286→              caught = true;
   287→            } catch (innerE) {
   288→              if (innerE.isReturn || innerE.isBreak || innerE.isContinue) {
   289→                throw innerE;
   290→              }
   291→              throw innerE;
   292→            }
   293→          } else {
   294→            throw e;
   295→          }
   296→        } finally {
   297→          if (node.finallyBlock) {
   298→            this.eval(node.finallyBlock, env);
   299→          }
   300→        }
   301→
   302→        return result;
   303→      }
   304→
   305→      if (node instanceof ThrowStatement) {
   306→        const value = this.eval(node.argument, env);
   307→        const error = new Error(value);
   308→        error.thrownValue = value;
   309→        throw error;
   310→      }
   311→
   312→      if (node instanceof BinaryExpression) {
   313→        const left = this.eval(node.left, env);
   314→        const right = this.eval(node.right, env);
   315→
   316→        switch (node.operator) {
   317→          case '+': return left + right;
   318→          case '-': return left - right;
   319→          case '*': return left * right;
   320→          case '/': return left / right;
   321→          case '%': return left % right;
   322→          case '**': return Math.pow(left, right);
   323→          case '==': return left == right;
   324→          case '===': return left === right;
   325→          case '!=': return left != right;
   326→          case '!==': return left !== right;
   327→          case '<': return left < right;
   328→          case '<=': return left <= right;
   329→          case '>': return left > right;
   330→          case '>=': return left >= right;
   331→          case '&': return left & right;
   332→          case '|': return left | right;
   333→          case '^': return left ^ right;
   334→          case '<<': return left << right;
   335→          case '>>': return left >> right;
   336→          default:
   337→            throw new Error(`Unknown binary operator: ${node.operator}`);
   338→        }
   339→      }
   340→
   341→      if (node instanceof UnaryExpression) {
   342→        // Handle ? operator (error propagation)
   343→        if (node.operator === '?') {
   344→          const arg = this.eval(node.argument, env);
   345→          // Check if arg is an error-like object (Result type)
   346→          if (arg && typeof arg === 'object' && arg.isErr) {
   347→            // Propagate error by returning it
   348→            throw new Error(`Error: ${arg.value || 'unknown error'}`);
   349→          }
   350→          return arg;
   351→        }
   352→
   353→        const arg = this.eval(node.argument, env);
   354→
   355→        switch (node.operator) {
   356→          case '+': return +arg;
   357→          case '-': return -arg;
   358→          case '!': return !this.isTruthy(arg);
   359→          case '~': return ~arg;
   360→          default:
   361→            throw new Error(`Unknown unary operator: ${node.operator}`);
   362→        }
   363→      }
   364→
   365→      if (node instanceof LogicalExpression) {
   366→        const left = this.eval(node.left, env);
   367→
   368→        if (node.operator === '||' || node.operator === 'or') {
   369→          return this.isTruthy(left) ? left : this.eval(node.right, env);
   370→        }
   371→        if (node.operator === '&&' || node.operator === 'and') {
   372→          return this.isTruthy(left) ? this.eval(node.right, env) : left;
   373→        }
   374→
   375→        throw new Error(`Unknown logical operator: ${node.operator}`);
   376→      }
   377→
   378→      if (node instanceof ConditionalExpression) {
   379→        const test = this.isTruthy(this.eval(node.test, env));
   380→        return test ? this.eval(node.consequent, env) : this.eval(node.alternate, env);
   381→      }
   382→
   383→      if (node instanceof CallExpression) {
   384→        const callee = this.eval(node.callee, env);
   385→        const args = node.args.map(arg => this.eval(arg, env));
   386→
   387→        if (callee instanceof FreeLangFunction) {
   388→          return callee.call(this, args);
   389→        } else if (typeof callee === 'function') {
   390→          // Native function
   391→          return callee(...args);
   392→        }
   393→
   394→        throw new Error(`Not a function: ${typeof callee}`);
   395→      }
   396→
   397→      if (node instanceof MemberExpression) {
   398→        const object = this.eval(node.object, env);
   399→
   400→        if (node.computed) {
   401→          const property = this.eval(node.property, env);
   402→          return object[property];
   403→        } else {
   404→          const property = node.property.name;
   405→          return object[property];
   406→        }
   407→      }
   408→
   409→      if (node instanceof AssignmentExpression) {
   410→        const value = this.eval(node.right, env);
   411→
   412→        if (node.left instanceof Identifier) {
   413→          const name = node.left.name;
   414→
   415→          switch (node.operator) {
   416→            case '=':
   417→              env.set(name, value);
   418→              break;
   419→            case '+=':
   420→              env.set(name, env.get(name) + value);
   421→              break;
   422→            case '-=':
   423→              env.set(name, env.get(name) - value);
   424→              break;
   425→            case '*=':
   426→              env.set(name, env.get(name) * value);
   427→              break;
   428→            case '/=':
   429→              env.set(name, env.get(name) / value);
   430→              break;
   431→            default:
   432→              throw new Error(`Unknown assignment operator: ${node.operator}`);
   433→          }
   434→
   435→          return value;
   436→        }
   437→
   438→        if (node.left instanceof MemberExpression) {
   439→          const object = this.eval(node.left.object, env);
   440→          const property = node.left.computed
   441→            ? this.eval(node.left.property, env)
   442→            : node.left.property.name;
   443→
   444→          switch (node.operator) {
   445→            case '=':
   446→              object[property] = value;
   447→              break;
   448→            case '+=':
   449→              object[property] = object[property] + value;
   450→              break;
   451→            case '-=':
   452→              object[property] = object[property] - value;
   453→              break;
   454→            case '*=':
   455→              object[property] = object[property] * value;
   456→              break;
   457→            case '/=':
   458→              object[property] = object[property] / value;
   459→              break;
   460→          }
   461→
   462→          return value;
   463→        }
   464→
   465→        throw new Error('Invalid assignment target');
   466→      }
   467→
   468→      if (node instanceof ArrayExpression) {
   469→        return node.elements.map(elem => elem ? this.eval(elem, env) : null);
   470→      }
   471→
   472→      if (node instanceof ObjectExpression) {
   473→        const obj = {};
   474→        for (const prop of node.properties) {
   475→          const key = prop.key.value;
   476→          const value = this.eval(prop.value, env);
   477→          obj[key] = value;
   478→        }
   479→        return obj;
   480→      }
   481→
   482→      if (node instanceof FunctionExpression) {
   483→        return new FreeLangFunction(node.params, node.body, env, node.name);
   484→      }
   485→
   486→      if (node instanceof Identifier) {
   487→        return env.get(node.name);
   488→      }
   489→
   490→      if (node instanceof FStringLiteral) {
   491→        let result = '';
   492→        for (const part of node.parts) {
   493→          if (part.type === 'string') {
   494→            result += part.value;
   495→          } else if (part.type === 'expression') {
   496→            // Evaluate the expression and convert to string
   497→            const exprValue = this.eval(part.value, env);
   498→            result += String(exprValue);
   499→          }
   500→        }
   501→        return result;
   502→      }
   503→
   504→      if (node instanceof Literal) {
   505→        return node.value;
   506→      }
   507→
   508→      throw new Error(`Unknown node type: ${node.type || node.constructor.name}`);
   509→    } finally {
   510→      this.currentEnv = prevEnv;
   511→    }
   512→  }
   513→
   514→  executeBlock(statements, env) {
   515→    let result = null;
   516→    for (const stmt of statements) {
   517→      result = this.eval(stmt, env);
   518→    }
   519→    return result;
   520→  }
   521→
   522→  isTruthy(value) {
   523→    if (value === null || value === undefined) return false;
   524→    if (typeof value === 'boolean') return value;
   525→    if (typeof value === 'number') return value !== 0;
   526→    if (typeof value === 'string') return value.length > 0;
   527→    return true;
   528→  }
   529→}
   530→
   531→module.exports = { Evaluator, Environment, FreeLangFunction };
