    76→fn allocate_numa_local(opt: MemoryOptimizer, size: i32, numa_node: i32) -> bool {
    77→  let key = to_string(numa_node);
    78→  if !contains(opt.numa_nodes, key) {
    79→    return false;  // Invalid node
    80→  }
    81→
    82→  let node = get(opt.numa_nodes, key);
    83→
    84→  // Check capacity
    85→  if node.allocated + size > node.capacity {
    86→    return false;  // Out of memory
    87→  }
    88→
    89→  node.allocated = node.allocated + size;
    90→  node.access_count = node.access_count + 1;
    91→  push(node.memory_objects, node.allocated - size);
    92→  set(opt.numa_nodes, key, node);
    93→
    94→  opt.total_allocated = opt.total_allocated + size;
    95→  return true;
    96→}
