   119→fn calculate_numa_imbalance(opt: MemoryOptimizer) -> i32 {
   120→  let keys = keys(opt.numa_nodes);
   121→  let mut max_alloc = 0;
   122→  let mut min_alloc = 999999;
   123→
   124→  for i in 0..length(keys) {
   125→    let key = keys[i];
   126→    let node = get(opt.numa_nodes, key);
   127→
   128→    if node.allocated > max_alloc {
   129→      max_alloc = node.allocated;
   130→    }
   131→    if node.allocated < min_alloc {
   132→      min_alloc = node.allocated;
   133→    }
   134→  }
   135→
   136→  let imbalance = if max_alloc > 0 {
   137→    ((max_alloc - min_alloc) * 100) / max_alloc
   138→  } else {
   139→    0
   140→  };
   141→
   142→  // R7: NUMA data movement < 10%
   143→  return imbalance;
   144→}
