   146→fn layout_object_cache_friendly(opt: MemoryOptimizer, obj_id: i32,
   147→                               fields: any, hot_field_count: i32) -> bool {
   148→  let layout = CacheLayout {
   149→    object_id: obj_id,
   150→    offset: 0,
   151→    aligned: false,
   152→    cache_line_addr: 0,
   153→    hot_fields: array(),
   154→    field_count: length(fields),
   155→    padding_bytes: 0
   156→  };
   157→
   158→  // Arrange hot fields first for cache locality
   159→  for i in 0..hot_field_count {
   160→    if i < length(fields) {
   161→      push(layout.hot_fields, fields[i]);
   162→    }
   163→  }
   164→
   165→  // Align to 64-byte cache line
   166→  let total_size = layout.field_count * 8;  // 8 bytes per field
   167→  let aligned_size = ((total_size + 63) / 64) * 64;
   168→  layout.padding_bytes = aligned_size - total_size;
   169→  layout.aligned = true;
   170→  layout.cache_line_addr = (obj_id * 64) & ~63;  // Align to 64-byte boundary
   171→
   172→  let key = to_string(obj_id);
   173→  set(opt.cache_layouts, key, layout);
   174→
   175→  return true;
   176→}
